class Processor(Iface, TProcessor):
    def __init__(self, handler):
        self._handler = handler
        self._processMap = {}
        self._processMap["saveAssociationRule"] = Processor.process_saveAssociationRule
        self._processMap["queryAssociationRules"] = Processor.process_queryAssociationRules
        self._processMap["countAssociationRules"] = Processor.process_countAssociationRules
        self._processMap["getAssociationRule"] = Processor.process_getAssociationRule
